/// Draw a modal overlay that blocks input to the canvas when any dialog is open.
/// This prevents cursor pass-through where clicks go through panels/windows into the canvas.
fn draw_modal_overlay(ui: &Ui, app: &FireCraft) {
    let any_dialog_open = app.show_new_dialog
        || app.show_canvas_size_dialog
        || app.show_find_replace
        || app.show_commands_dialog
        || app.show_command_palette
        || app.show_mcp_dialog
        || app.show_about_dialog
        || app.show_file_dialog
        || app.show_welcome;

    if !any_dialog_open {
        return;
    }

    // Draw a semi-transparent overlay covering the entire screen to block input
    let screen_rect = ui.ctx().screen_rect();
    ui.painter().rect_filled(
        screen_rect,
        0.0,
        egui::Color32::from_rgba_premultiplied(0, 0, 0, 80),
    );

    // Draw a centered message
    let message = "A dialog is open — click OK/Cancel to close it first";
    let font_id = egui::FontId::monospace(12.0);
    let measured = ui.fonts(|f| f.layout_no_wrap(message.to_string(), font_id, 400.0));
    let text_pos = screen_rect.center() - egui::Vec2::new(measured.size().x / 2.0, measured.size().y / 2.0);
    ui.painter().text(
        text_pos,
        egui::Align2::LEFT_CENTER,
        message,
        font_id,
        egui::Color32::WHITE,
    );

    // Prevent input events from reaching underlying panels
    ui.ctx().set_cursor_icon(egui::CursorIcon::NotAllowed);
}

